"""추가 여성 제독 13종의 일기토와 필살기 원화 제작 지시문을 준비한다."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
RECORD=ROOT/'tools/hero_women_20261124'
RAW=ROOT/'art_sources/hero-women-20261124/raw'
COMMON='''Use case: stylized-concept. Production transparent sprite atlas for historical maritime RPG, detailed realistic painterly game illustration. Reference 1 is the original adult woman's head-to-knees outfit, reference 2 is her face. Preserve EXACT same adult woman's face, hair, opaque clothing, colors, short skirt/shorts, armor, accessories and body proportions, complete her legs with the same practical tall leather boots. Keep occupational tools, books, bows, quiver and map cases secured at belt or back. Wield ONLY ONE simple gold-guard European rapier/saber in her RIGHT hand. Anatomically correct five-digit grip: four fingers wrap around and occlude the leather hilt, thumb opposes over fingers, guard in front of knuckles, pommel behind little finger. Blade firmly attached to hilt; wrist connected naturally to forearm. No floating weapons, disconnected handles, extra limbs, extra fingers, gore or motion trails. EXACTLY 24 fully visible full-body poses in STRICT 6 columns by 4 rows, landscape 2304x1536. All whole figures including boots, fingers, sword tips and cloth safely inside their equal cells with generous transparent gutters. Consistent same body scale, camera, right-facing three-quarter side view. Genuine ALPHA ZERO background everywhere outside silhouettes, no floor, shadows, white/gray haze, background, labels, text, watermarks or grid lines. Do not crop any figure or sword tip. '''
ATK='''Solo non-contact theatrical fencing practice, with no opponent or harm. Four six-frame actions in left-to-right row order: row 1 overhead saber slash (ready, windup, high arc, downward cut, followthrough, recovery); row 2 horizontal thrust (guard, pull back, extend, full lunge, recoil, recovery); row 3 low sweeping cut (crouch windup, draw back, swing, extension, followthrough, recover); row 4 short pommel bash (guard, pull back, step in, pommel forward, followthrough, recover). Each keyframe clearly changes arm, wrist, blade and leg positions, while keeping the same right hand firmly gripping the hilt.'''
REACT='''Four rows in exact left-to-right order. Row 1 parry (neutral ready, high guard, blade parry, bracing, relax, neutral). Row 2 defense (guard, low guard, middle guard, stepping back, regain balance, neutral). Row 3 hit reaction (flinch, recoil, clutch side with free hand, stumble back, regain balance, neutral). Row 4 EXACTLY: 1 neutral standing sword low; 2 command raised free hand; 3 kneel on ONE knee; 4 collapsing low; 5 LYING COMPLETELY FLAT HORIZONTALLY ON THE GROUND in side view, full extended body head to boots, width at least THREE TIMES its height, no raised knees or torso; 6 rising to kneel. The prone figure in row 4 column 5 must fit horizontally in its own square cell, with entire head, hair and boots visible. No blood, no wounds.'''
CUTIN='''Use case: illustration-story. Dramatic SPECIAL ATTACK event illustration for historical maritime RPG. Reference 1 is this adult woman's exact costume, Reference 2 her facial identity. Preserve her face, hairstyle, age and opaque costume and colors exactly. Same practical tall boots. Dynamic sword lunge toward RIGHT, protagonist fills LEFT two thirds, upper-thigh framing, face fierce and focused, wind in hair and cloth. ONE gold-guard European saber held in RIGHT hand with an especially clear anatomically correct FIVE-digit closed grip: FOUR curled fingers completely wrap and occlude the leather hilt, thumb visibly opposes across index/middle fingers, continuous natural wrist and forearm. Guard lies between knuckles and blade, pommel extends behind little finger. Show grip from a readable oblique angle, no foreshortening obscuring the grip. Sword must be firmly enclosed in palm, never floating under a fist. Left hand open and empty, all occupational equipment secured at belt/back, bow sheathed on back if present. Rich cinematic hand-painted realistic game illustration with gold blade streaks, sea spray and a storm-lit sailing ship deck background. Luminous rim light. Landscape 1536x640, fully opaque finished scene. No opponent, no text, borders, logos, watermark or gore. No other people. No extra swords, fingers or floating props.'''

def main():
    RECORD.mkdir(parents=True,exist_ok=True);RAW.mkdir(parents=True,exist_ok=True)
    chars=[c for c in json.loads((ROOT/'tools/hero_street_20261124/characters.json').read_text(encoding='utf-8')) if c['id'].endswith('_f')]
    jobs=[]
    for c in chars:
        fid=c['id'];refs=ROOT/'art_sources/hero-street-20261124/references'
        for kind,prompt in [('atk',COMMON+ATK),('react',COMMON+REACT),('cutin',CUTIN)]:
            jobs.append({'id':fid,'name':c['name'],'key':fid+'_'+kind,'kind':kind,'references':[str(refs/(fid+'_knee.png')),str(refs/(fid+'_face.png'))],'prompt':prompt})
    (RECORD/'characters.json').write_text(json.dumps(chars,ensure_ascii=False,indent=2),encoding='utf-8')
    (RECORD/'jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'여성 {len(chars)}종 · 공격/반응 시트와 사건샷 {len(jobs)}장')

if __name__=='__main__':main()
